"use strict";

// Atomic persistence boundary. State and UI updates belong to the caller.
globalThis.EduRecordTransaction = Object.freeze({
  async commit({
    connection,
    expectedInstallation = "",
    workspace,
    records,
    changed,
    removed,
    before,
    changes,
    action,
    keepUndo,
    normalizedName,
    academicTermKind,
    annualChanged,
    decodeRecords,
    historicalRoster,
    directorySourceUpdates,
    directoryRevisions,
    scheduleResolution,
    recoveredUndo,
    restoredSessionRecords,
  }) {
    const directoryTransaction = globalThis.EduAcademicDirectoryTransaction;
    if (
      directoryTransaction?.hasChanges({
        records,
        changed,
        removed,
        before,
        scheduleResolution,
      })
    )
      return directoryTransaction.commit({
        connection,
        expectedInstallation,
        workspace,
        records,
        changed,
        removed,
        before,
        changes,
        action,
        keepUndo,
        normalizedName,
        academicTermKind,
        annualChanged,
        decodeRecords,
        historicalRoster,
        directorySourceUpdates,
        directoryRevisions,
        scheduleResolution,
        recoveredUndo,
        restoredSessionRecords,
      });
    // Compare against the request's original catalog, not a live UI object
    // that can change before IndexedDB delivers its callbacks.
    workspace = { ...workspace };
    const { transactionDone } = globalThis.EduDataStoreRuntime;
    const recordKey = (logical) => workspace.id + "|" + logical;
    const tx = connection.transaction(
        ["records", "catalog", "events", "undo"],
        "readwrite",
      ),
      done = transactionDone(tx);
    let conflict = false,
      labelConflict = false,
      nextCatalog,
      queueError;
    const annualUpdates = [];
    const abortQueue = (error) => {
      queueError = error;
      try {
        tx.abort();
      } catch (ignore) {}
    };
    try {
      // Queue this read first: IndexedDB delivers requests in transaction order.
      // No source, mirrored grade, history or undo write may precede it.
      const epoch = tx.objectStore("records").get("@installation-reset");
      epoch.onsuccess = () => {
        if ((epoch.result?.value?.token || "") !== expectedInstallation)
          abortQueue(
            Object.assign(
              Error(
                "اطلاعات در پنجرهٔ دیگری جایگزین شده است؛ صفحه را دوباره باز کنید.",
              ),
              { code: "INSTALLATION_CHANGED" },
            ),
          );
      };
      const catalog = tx.objectStore("catalog"),
        sessionSlots = globalThis.EduSessionSlots,
        sessionChanges = sessionSlots?.changes({
          changed,
          before,
          removed,
          restoredRecords: restoredSessionRecords,
        }),
        sourceMeta = records.get("meta"),
        meta = sourceMeta ? { settings: { ...sourceMeta.settings } } : null,
        sourceLayout = sourceMeta?.layout
          ? JSON.parse(JSON.stringify(sourceMeta.layout))
          : [],
        annualModel = globalThis.EduAnnualModules,
        annualPlans = annualModel
          ? changed.flatMap(([logical, json]) => {
              if (!logical.startsWith("class:")) return [];
              const previous = before.find((row) => row.key === logical)?.value;
              const current = JSON.parse(json);
              if (logical !== "class:" + current?.id)
                throw Error("شناسهٔ کلاس با رکورد ثبت نمره سازگار نیست.");
              if (!annualModel.hasChanges(previous, current)) return [];
              const owners = sourceLayout.filter((school) =>
                school.classes?.includes(current.id),
              );
              if (owners.length !== 1)
                throw Error("مالک کلاس برای ثبت نمرهٔ سالانه مشخص نیست.");
              return [
                {
                  logical,
                  previous: previous
                    ? JSON.parse(JSON.stringify(previous))
                    : null,
                  current,
                  schoolId: owners[0].id,
                },
              ];
            })
          : [],
        labelChanged =
          meta &&
          (meta.settings?.academicYear !== workspace.year ||
            meta.settings?.academicTerm !== workspace.term),
        labels =
          labelChanged || annualPlans.length || sessionChanges?.guarded.length
            ? catalog.getAll()
            : null,
        get = catalog.get(workspace.id);
      get.onsuccess = () => {
        if (queueError) return;
        try {
          const live = get.result;
          if (!live || live.revision !== workspace.revision) {
            conflict = true;
            tx.abort();
            return;
          }
          if (
            labelChanged &&
            labels.result.some(
              (row) =>
                row.id !== workspace.id &&
                row.year === meta.settings.academicYear &&
                normalizedName(row.term) ===
                  normalizedName(meta.settings.academicTerm),
            )
          ) {
            labelConflict = true;
            tx.abort();
            return;
          }
          if (sessionChanges?.guarded.length) {
            sessionSlots.assertScheduled(sessionChanges, sourceMeta);
            const year = meta?.settings?.academicYear ?? live.year,
              family = labels.result.filter(
                (row) =>
                  row.id === live.id ||
                  (row.year === year &&
                    ["first", "second"].includes(
                      row.termKind || academicTermKind(row.term),
                    )),
              ),
              parts = [];
            let pending = family.length;
            // Reads share the write transaction's lock with every competing
            // term save. A peer cannot insert the same slot after this check
            // but before our write commits; any conflict aborts all stores.
            for (const period of family) {
              const request = tx
                .objectStore("records")
                .getAll(
                  IDBKeyRange.bound(
                    period.id + "|session:",
                    period.id + "|session;",
                    false,
                    true,
                  ),
                );
              request.onsuccess = () => {
                try {
                  parts.push({
                    id: period.id,
                    records: new Map(
                      request.result.map((row) => [row.logical, row.value]),
                    ),
                  });
                  if (!--pending)
                    sessionSlots.assertAvailable(
                      sessionChanges,
                      live.id,
                      parts,
                    );
                } catch (error) {
                  abortQueue(error);
                }
              };
            }
          }
          for (const [logical, json] of changed)
            tx.objectStore("records").put({
              key: recordKey(logical),
              workspace: workspace.id,
              logical,
              value: JSON.parse(json),
            });
          for (const logical of removed)
            tx.objectStore("records").delete(recordKey(logical));
          const next = {
            ...live,
            year: meta?.settings?.academicYear ?? live.year,
            term: meta?.settings?.academicTerm ?? live.term,
            // Editing the display label must not move grades between annual
            // terms. For legacy rows infer the role from the original label.
            termKind: live.termKind || academicTermKind(live.term),
            revision: live.revision + 1,
            updatedAt: new Date().toISOString(),
          };
          const annualCompanions = [];
          if (
            annualPlans.length &&
            ["first", "second"].includes(next.termKind)
          ) {
            const roles = new Set();
            for (const period of labels.result) {
              const candidate = period.id === next.id ? next : period;
              if (candidate.year !== next.year) continue;
              const kind =
                candidate.termKind || academicTermKind(candidate.term);
              if (kind !== "first" && kind !== "second") continue;
              if (roles.has(kind))
                throw Error("نوبت‌های سال برای ثبت نمرهٔ سالانه تکراری‌اند.");
              roles.add(kind);
              if (candidate.id !== next.id) annualCompanions.push(candidate);
            }
          }
          nextCatalog = next;
          catalog.put(next);
          tx.objectStore("events").add({
            workspace: workspace.id,
            at: next.updatedAt,
            action,
            revision: next.revision,
            changes,
          });
          if (keepUndo)
            tx.objectStore("undo").put({
              id: workspace.id,
              action,
              revision: next.revision,
              before,
            });
          else tx.objectStore("undo").delete(workspace.id);
          // These requests stay inside the live IndexedDB callback. Source and
          // companion grades either all commit, or none of them do.
          for (const companion of annualCompanions) {
            const companionMeta = tx
              .objectStore("records")
              .get(companion.id + "|meta");
            companionMeta.onsuccess = () => {
              try {
                const metaRow = companionMeta.result,
                  layout = metaRow?.value?.layout;
                if (
                  metaRow?.workspace !== companion.id ||
                  metaRow?.logical !== "meta" ||
                  metaRow?.key !== companion.id + "|meta" ||
                  !Array.isArray(layout)
                )
                  throw Error("چیدمان نوبت برای ثبت نمرهٔ سالانه معتبر نیست.");
                let pending = 0;
                const companionChanges = [];
                const finishCompanion = () => {
                  if (pending || !companionChanges.length) return;
                  const synchronized = {
                    ...companion,
                    revision: companion.revision + 1,
                    updatedAt: next.updatedAt,
                  };
                  catalog.put(synchronized);
                  tx.objectStore("events").add({
                    workspace: companion.id,
                    at: synchronized.updatedAt,
                    action: "همگام‌سازی نمرهٔ سالانهٔ پودمان",
                    revision: synchronized.revision,
                    changes: companionChanges,
                  });
                  // An undo prepared before this annual update is now stale.
                  tx.objectStore("undo").delete(companion.id);
                  annualUpdates.push({
                    workspace: companion.id,
                    revision: synchronized.revision,
                  });
                };
                for (const plan of annualPlans) {
                  const owners = layout.filter((school) =>
                    school.classes?.includes(plan.current.id),
                  );
                  if (!owners.length) continue;
                  if (owners.length !== 1)
                    throw Error("کلاس در چیدمان نوبت تکرار شده است.");
                  if (owners[0].id !== plan.schoolId) continue;
                  pending++;
                  const request = tx
                    .objectStore("records")
                    .get(companion.id + "|" + plan.logical);
                  request.onsuccess = () => {
                    try {
                      const row = request.result;
                      if (
                        !row ||
                        row.key !== companion.id + "|" + plan.logical ||
                        row.workspace !== companion.id ||
                        row.logical !== plan.logical ||
                        row.value?.id !== plan.current.id
                      )
                        throw Error(
                          "رکورد کلاس برای ثبت نمرهٔ سالانه معتبر نیست.",
                        );
                      const value = annualModel.mirrorClass(
                        plan.previous,
                        plan.current,
                        row.value,
                      );
                      if (
                        value &&
                        JSON.stringify(value) !== JSON.stringify(row.value)
                      ) {
                        tx.objectStore("records").put({ ...row, value });
                        companionChanges.push({
                          path: plan.logical + ".annualModules",
                          before: null,
                          after: "نمره‌های سالانهٔ پودمان همگام شد",
                        });
                      }
                      pending--;
                      finishCompanion();
                    } catch (error) {
                      abortQueue(error);
                    }
                  };
                }
              } catch (error) {
                abortQueue(error);
              }
            };
          }
        } catch (error) {
          abortQueue(error);
        }
      };
    } catch (error) {
      abortQueue(error);
    }
    try {
      await done;
    } catch (e) {
      if (labelConflict)
        throw Error(
          "ترم دیگری با همین سال و عنوان نوبت وجود دارد؛ عنوان متمایز انتخاب کنید.",
          { cause: e },
        );
      if (conflict) {
        const error = Error(
          "داده در تب دیگری تغییر کرده است؛ برای جلوگیری از بازنویسی، صفحه را دوباره بارگذاری کنید.",
          { cause: e },
        );
        error.code = "WORKSPACE_CONFLICT";
        throw error;
      }
      throw queueError || e;
    }
    if (annualChanged) annualChanged.push(...annualUpdates);
    return nextCatalog;
  },
});
